WITH lp AS ( SELECT cr, pack_id FROM cr_in_pack UNION SELECT cr, pack_id FROM pack_member ), ls AS ( SELECT cr, section_id FROM cr_modifies_section UNION SELECT cr, section_id FROM section_modified_by ), dk AS ( SELECT id AS doc_id, id AS k FROM document UNION SELECT id AS doc_id, number AS k FROM document WHERE number IS NOT NULL ), pk AS ( SELECT id AS pid, id AS k FROM cr_pack UNION SELECT id AS pid, pack_number AS k FROM cr_pack WHERE pack_number IS NOT NULL ), docs AS ( SELECT id AS doc_id, COALESCE(number, id) AS docnum, CAST(ltrim(replace(replace(replace(replace(replace(upper(trim(target_release)), 'RELEASE', ''), 'REL', ''), '-', ''), ' ', ''), '_', ''), 'RV.') AS INTEGER) AS trel FROM document ), cp_map AS ( SELECT DISTINCT dk.doc_id AS doc_id, pk.pid AS pid FROM lp JOIN dk ON dk.k = lp.cr JOIN pk ON pk.k = lp.pack_id ), cs_map AS ( SELECT DISTINCT dk.doc_id AS doc_id, s.spec AS spec, s.clause AS clause, CAST(ltrim(replace(replace(replace(replace(replace(upper(trim(s."release")), 'RELEASE', ''), 'REL', ''), '-', ''), ' ', ''), '_', ''), 'RV.') AS INTEGER) AS rel FROM ls JOIN dk ON dk.k = ls.cr JOIN section s ON s.id = ls.section_id ), gd AS ( SELECT DISTINCT dk.doc_id AS doc_id, disp.code AS code, m.label AS wg_label FROM disposition disp JOIN dk ON dk.k = disp.target JOIN resolution r ON r.id = disp.resolution_id JOIN meeting m ON m.id = r.meeting_id WHERE (replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') LIKE '%sourceverified%' OR replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') IN ('verifiedsource', 'verifiedfromsource', 'verifiedagainstsource')) AND replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') NOT LIKE '%not%' AND replace(replace(replace(lower(trim(disp.evidence_status)), '_', ''), '-', ''), ' ', '') NOT LIKE '%unverified%' AND replace(replace(replace(lower(trim(disp.scope)), '_', ''), '-', ''), ' ', '') IN ('document', 'wholedocument', 'whole', 'wholedoc', 'fulldocument', 'full', 'entiredocument', 'entire', 'doc') AND (replace(replace(replace(upper(trim(m.wg)), '_', ''), '-', ''), ' ', '') LIKE '%RAN3%' OR replace(replace(replace(upper(trim(m.wg)), '_', ''), '-', ''), ' ', '') LIKE '%RANWG3%' OR replace(replace(replace(upper(trim(m.wg)), '_', ''), '-', ''), ' ', '') IN ('R3', 'WG3')) ), anchor AS ( SELECT id AS doc_id FROM document WHERE number = '{ANCHOR}' OR id = '{ANCHOR}' ), asec AS ( SELECT DISTINCT cs.spec AS spec, cs.clause AS clause, cs.rel AS rel FROM anchor a JOIN cs_map cs ON cs.doc_id = a.doc_id WHERE cs.rel = 17 ) SELECT DISTINCT asec.clause AS clause, d2.docnum AS document, gd.code AS disposition, gd.wg_label AS wg_meeting, COALESCE(p.pack_number, p.id) AS cr_pack FROM asec JOIN cs_map cs2 ON cs2.spec = asec.spec AND cs2.clause = asec.clause AND cs2.rel = asec.rel JOIN docs d2 ON d2.doc_id = cs2.doc_id AND d2.trel = 17 JOIN gd ON gd.doc_id = d2.doc_id JOIN cp_map cm ON cm.doc_id = d2.doc_id JOIN cr_pack p ON p.id = cm.pid WHERE d2.doc_id NOT IN (SELECT doc_id FROM anchor) AND d2.docnum <> '{ANCHOR}'
